                r, c = q.popleft()
                cells.append((r, c))
                r0, r1 = min(r0, r), max(r1, r)
                c0, c1 = min(c0, c), max(c1, c)
                for nr, nc in ((r-1, c), (r+1, c), (r, c-1), (r, c+1)):
